import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import firebase from 'firebase/compat/app';
import 'firebase/compat/auth';
import './styles/SignInPage.css';
import { FaArrowLeft } from 'react-icons/fa';

const TermsModal = ({ show, onClose }) => {
  if (!show) return null;

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <h3>Terms and Conditions</h3>
        <p>
          Welcome to the MIS System. By creating an account, you agree to comply
          with our rules and regulations. Please read our terms carefully before proceeding.
        </p>
        <h1 className="terms-title">Terms and Conditions</h1>
      <p className="terms-text">
        Welcome to MIS System! These terms outline the rules for using our services.
      </p>
      <div className="terms-content">
        <h2>Effective Date: 25/11/24</h2>
        <p>
          Welcome to MIS System! These Terms and Conditions govern your use of our platform, 
          designed to send or request job assignments. By accessing or using MIS System, you agree to these terms. If you do not agree, please discontinue use.
        </p>
        <ol>
          <li>
            <strong>Acceptance of Terms:</strong> By using this system, you confirm that you are at least 18 years old and capable of entering into legally binding agreements.
          </li>
          <li>
            <strong>Purpose and Use:</strong>
            <ul>
              <li>The platform allows users to send or request job assignments securely and efficiently.</li>
              <li>Access to the system is provided exclusively via email or Google Sign-In.</li>
              <li>You agree to use the platform only for its intended purpose and in compliance with applicable laws and these terms.</li>
            </ul>
          </li>
          <li>
            <strong>User Accounts and Authentication:</strong>
            <ul>
              <li>Users must log in via email or Google Sign-In.</li>
              <li>You are responsible for maintaining the confidentiality of your login credentials.</li>
              <li>Unauthorized access or use of another person's credentials is prohibited.</li>
            </ul>
          </li>
          <li>
            <strong>Data Privacy and Security:</strong> Your data is handled in accordance with our Privacy Policy.
          </li>
          <li>
            <strong>Restrictions:</strong> You may not use the system for unauthorized purposes, spamming, or any activity that disrupts the functionality of the system.
          </li>
          <li>
            <strong>System Availability:</strong> While we aim to ensure uninterrupted access, we do not guarantee that the platform will be error-free or always available.
          </li>
          <li>
            <strong>Intellectual Property:</strong> The system, including its features, content, and design, is the property of MIS System.
          </li>
          <li>
            <strong>Updates and Modifications:</strong> Continued use of the system after changes constitutes acceptance of the revised terms.
          </li>
          <li>
            <strong>Termination of Access:</strong> We reserve the right to suspend or terminate user access for violations of these terms or misuse of the system.
          </li>
          <li>
            <strong>Governing Law:</strong> These Terms and Conditions are governed by the laws of Philippines.
          </li>
          <li>
            <strong>Contact Us:</strong> For any inquiries, email us at <a href="mailto:mis@consolidatedcoconut.com.ph">mis@consolidatedcoconut.com.ph</a>.
          </li>
        </ol>
        </div>
        <button onClick={onClose} className="modal-close-button">
          Close
        </button>
      </div>
    </div>
  );
};

const SignInPage = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [step, setStep] = useState(1); // 1: Email, 2: Password
  const [isLogin, setIsLogin] = useState(true); // Default to login
  const [error, setError] = useState(null); // For error messages
  const [isChecked, setIsChecked] = useState(false); // For the checkbox
  const [showModal, setShowModal] = useState(false); // Modal state
  const navigate = useNavigate();

  useEffect(() => {
    const unsubscribe = firebase.auth().onAuthStateChanged((user) => {
      if (user) {
        setIsAuthenticated(true);
        navigate('/dashboard');
      } else {
        setIsAuthenticated(false);
      }
    });

    return () => unsubscribe();
  }, [navigate]);

  const handleGoogleSignIn = () => {
    const provider = new firebase.auth.GoogleAuthProvider();
    firebase
      .auth()
      .signInWithPopup(provider)
      .then((result) => {
        console.log('User signed in:', result.user);
      })
      .catch((error) => {
        console.error('Login error:', error);
      });
  };

  const handleEmailContinue = (e) => {
    e.preventDefault();
    setError(null); // Clear any previous errors
    setStep(2); // Move to password step
  };

  const handlePasswordContinue = (e) => {
    e.preventDefault();
    setError(null); // Clear any previous errors

    if (!isLogin && !isChecked) {
      setError('You must agree to the Terms and Conditions.');
      return;
    }

    if (isLogin) {
      firebase
        .auth()
        .signInWithEmailAndPassword(email, password)
        .then((userCredential) => {
          const user = userCredential.user;
          if (user.emailVerified) {
            console.log('User logged in:', user);
            navigate('/dashboard');
          } else {
            setError('Please verify your email before signing in.');
          }
        })
        .catch((error) => {
          setError('Login error: ' + error.message);
        });
    } else {
      firebase
        .auth()
        .createUserWithEmailAndPassword(email, password)
        .then((userCredential) => {
          userCredential.user
            .sendEmailVerification()
            .then(() => {
              console.log('Verification email sent.');
              alert('Verification email sent. Please verify your email.');
              setIsLogin(true);
              setStep(1); // Reset to email step for login
            })
            .catch((error) => {
              setError('Error sending verification email: ' + error.message);
            });
        })
        .catch((error) => {
          if (error.code === 'auth/email-already-in-use') {
            setError('The email address is already in use by another account.');
          } else {
            setError('Error creating user: ' + error.message);
          }
        });
    }
  };

  const handleBack = () => {
    setStep(step - 1);
    setError(null); // Clear any previous errors
  };

  return (
    <div className="signin-page">
      <TermsModal show={showModal} onClose={() => setShowModal(false)} />
      {!isAuthenticated && (
        <div className="signin-card">
          <div className="back-button-container">
            {step === 2 && (
              <button className="back-button" onClick={handleBack}>
                <FaArrowLeft />
              </button>
            )}
          </div>
          <h2>Welcome to MIS System</h2>
          <p>Please sign in to continue</p>
          {error && <p className="error">{error}</p>}
          {step === 1 && (
            <form onSubmit={handleEmailContinue}>
              <label>{isLogin ? 'Sign In' : 'Create an Account'}</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="Enter your email"
                required
              />
              <button type="submit">Continue</button>
              {isLogin ? (
                <p className="toggle-text">
                  Don't have an account?{' '}
                  <span
                    onClick={() => {
                      setIsLogin(false);
                      setStep(1);
                      setError(null);
                    }}
                  >
                    Register
                  </span>
                </p>
              ) : (
                <p className="toggle-text">
                  Already have an account?{' '}
                  <span
                    onClick={() => {
                      setIsLogin(true);
                      setStep(1);
                      setError(null);
                    }}
                  >
                    Login
                  </span>
                </p>
              )}
            </form>
          )}
          {step === 2 && (
            <form onSubmit={handlePasswordContinue}>
              <label>{isLogin ? 'Sign In' : 'Create an Account'}</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder={isLogin ? 'Enter your password' : 'Create a password'}
                required
              />
              {!isLogin && (
                <div className="checkbox-container">
                  <input
                    type="checkbox"
                    id="terms"
                    checked={isChecked}
                    onChange={(e) => setIsChecked(e.target.checked)}
                  />
                  <label htmlFor="terms">
                    I agree to the{' '}
                    <span className="terms-link" onClick={() => setShowModal(true)}>
                      Terms and Conditions
                    </span>
                  </label>
                </div>
              )}
              <button type="submit">Continue</button>
            </form>
          )}
          <div className="separator">
            <span>Or</span>
          </div>
          <button className="google-signin-button" onClick={handleGoogleSignIn}>
            <img
              src="https://upload.wikimedia.org/wikipedia/commons/4/4a/Logo_2013_Google.png"
              alt="Google Logo"
            />
            Sign in with Google
          </button>
        </div>
      )}
    </div>
  );
};

export default SignInPage;
